{"tool": "sql", "args": {"query": "WITH RECURSIVE split(material, rest) AS (SELECT '', HTL_stack_sequence || ' | ' FROM devices WHERE Cell_architecture = 'nip' AND JV_default_PCE > 20 UNION ALL SELECT trim(substr(rest, 1, instr(rest, ' | ') - 1)), substr(rest, instr(rest, ' | ') + 3) FROM split WHERE rest != '') SELECT material, COUNT(*) as device_count, COUNT(DISTINCT Ref_DOI_number) as paper_count FROM split JOIN (SELECT rowid, Ref_DOI_number FROM devices WHERE Cell_architecture = 'nip' AND JV_default_PCE > 20) ON 1=1 WHERE material != '' AND material IS NOT NULL GROUP BY material ORDER BY device_count DESC LIMIT 20;"}}
